import math

from answer import first_bad


class Counted:
    def __init__(self, first):
        self.first = first
        self.calls = 0

    def __call__(self, i):
        self.calls += 1
        return i >= self.first


def test_finds_the_boundary():
    for n in (1, 2, 3, 7, 8, 9, 1000):
        for first in range(0, n):
            p = Counted(first)
            assert first_bad(p, n) == first, (n, first)


def test_none_when_all_good():
    p = Counted(10**9)
    assert first_bad(p, 64) is None


def test_empty():
    assert first_bad(Counted(0), 0) is None


def test_respects_call_budget():
    n = 1000
    for first in (0, 1, 499, 999):
        p = Counted(first)
        first_bad(p, n)
        assert p.calls <= math.ceil(math.log2(n)) + 1, (first, p.calls)
